extends Button
@export var action: StringName = &"move_left"
var previous_events: Array[InputEvent] = []
func _ready() -> void:
    toggle_mode = true
    set_process_unhandled_key_input(false)
    toggled.connect(_on_toggled)
    _show_binding()
func _on_toggled(active: bool) -> void:
    set_process_unhandled_key_input(active)
    if active:
        previous_events = InputMap.action_get_events(action).duplicate()
        text = "Press key (Esc cancels)"
    else:
        _show_binding()
        grab_focus()
func _unhandled_key_input(event: InputEvent) -> void:
    if not button_pressed or not event is InputEventKey:
        return
    if not event.pressed or event.echo:
        return
    get_viewport().set_input_as_handled()
    if event.keycode == KEY_ESCAPE:
        button_pressed = false
        return
    if event.keycode == KEY_ENTER or event.keycode == KEY_KP_ENTER:
        return
    for other in [&"move_left", &"move_right"]:
        if other == action:
            continue
        for bound in InputMap.action_get_events(other):
            if bound is InputEventKey and (bound.physical_keycode == event.physical_keycode if event.physical_keycode != 0 else bound.keycode == event.keycode):
                text = "Key conflict; choose another"
                return
    var normalized := InputEventKey.new()
    normalized.physical_keycode = event.physical_keycode
    normalized.keycode = event.keycode
    InputMap.action_erase_events(action)
    InputMap.action_add_event(action, normalized)
    KeyPersistence.keymaps[action] = normalized
    KeyPersistence.save_keymap()
    button_pressed = false
func _show_binding() -> void:
    var events := InputMap.action_get_events(action)
    text = events[0].as_text() if not events.is_empty() else "Unbound"
